  spdTips:           "typeof SPD_TIPS!=='undefined'?SPD_TIPS.length:'UNDEF'",
  r66_patternsHaveRequiredFields: "(function(){try{for(var i=0;i<SPD_PATTERNS.length;i++){var p=SPD_PATTERNS[i];if(!p.id||!p.template||!p.translit||!p.meaning||!p.category||!p.register)return 'BAD_'+i+':'+p.id;}return 'ok';}catch(e){return 'THROWS_'+e.message;}})()",
  r66_exercisesHaveRequiredFields: "(function(){try{for(var i=0;i<SPD_EXERCISES.length;i++){var e=SPD_EXERCISES[i];if(!e.id||!e.patternId||!e.blank||!e.full||!e.english||!e.options||e.options.length!==4||typeof e.correctIdx!=='number')return 'BAD_'+i+':'+e.id;}return 'ok';}catch(e){return 'THROWS_'+e.message;}})()",
  r66_exercisesReferenceRealPatterns: "(function(){try{var ids={};for(var i=0;i<SPD_PATTERNS.length;i++)ids[SPD_PATTERNS[i].id]=true;var miss=[];for(var j=0;j<SPD_EXERCISES.length;j++)if(!ids[SPD_EXERCISES[j].patternId])miss.push(SPD_EXERCISES[j].id+'->'+SPD_EXERCISES[j].patternId);return miss.length?'BAD_'+miss.join(','):'ok';}catch(e){return 'THROWS_'+e.message;}})()",
  r66_exerciseBlankAppearsInFull: "(function(){try{for(var i=0;i<SPD_EXERCISES.length;i++){var e=SPD_EXERCISES[i];if(e.full.indexOf(e.blank)<0)return 'MISSING_BLANK_'+e.id;}return 'ok';}catch(e){return 'THROWS_'+e.message;}})()",
  r66_correctIdxPointsToBlank: "(function(){try{for(var i=0;i<SPD_EXERCISES.length;i++){var e=SPD_EXERCISES[i];if(e.options[e.correctIdx]!==e.blank)return 'MISMATCH_'+e.id;}return 'ok';}catch(e){return 'THROWS_'+e.message;}})()",
  r66_optionsUniquePerExercise: "(function(){try{for(var i=0;i<SPD_EXERCISES.length;i++){var e=SPD_EXERCISES[i];var s={};for(var j=0;j<e.options.length;j++){if(s[e.options[j]])return 'DUPE_'+e.id+':'+e.options[j];s[e.options[j]]=true;}}return 'ok';}catch(e){return 'THROWS_'+e.message;}})()",
  r66_spdRegisteredInTopics: "(function(){try{for(var i=0;i<TOPICS_CATEGORIES.length;i++)for(var j=0;j<TOPICS_CATEGORIES[i].items.length;j++)if(TOPICS_CATEGORIES[i].items[j].fn==='openSpd')return 'ok_'+TOPICS_CATEGORIES[i].id;return 'MISSING';}catch(e){return 'THROWS_'+e.message;}})()",
  r66_spdAnswerIncrements: "(function(){try{_spdScore={correct:0,total:0};_spdBuildOrder();var before=_spdScore.total;spdAnswer(0);return _spdScore.total===before+1?'ok':'BAD_'+_spdScore.total;}catch(e){return 'THROWS_'+e.message;}})()",
  r66_spdCorrectIncrements: "(function(){try{_spdScore={correct:0,total:0};_spdBuildOrder();var ex=_spdCurrentExercise();spdAnswer(ex.correctIdx);return _spdScore.correct===1?'ok':'BAD_'+_spdScore.correct;}catch(e){return 'THROWS_'+e.message;}})()",
  r66_spdWrongDoesNotIncrementCorrect: "(function(){try{_spdScore={correct:0,total:0};_spdBuildOrder();var ex=_spdCurrentExercise();var wrong=(ex.correctIdx+1)%4;spdAnswer(wrong);return _spdScore.correct===0&&_spdScore.total===1?'ok':'BAD_c='+_spdScore.correct+'_t='+_spdScore.total;}catch(e){return 'THROWS_'+e.message;}})()",
