  r67_noDupeOnComplexInput: "(function(){try{var v=_audioKeyVariants('بكتابها');var s={};for(var i=0;i<v.length;i++){if(s[v[i]])return 'DUPE_'+v[i];s[v[i]]=true;}return 'ok';}catch(e){return 'THROWS_'+e.message;}})()",
  r67_hasAudioBareHitsPrefixed: "(function(){try{if(typeof YOUTUBE_AUDIO==='undefined')return 'NO_YT';var STEM='probe67stem';YOUTUBE_AUDIO[STEM]='stub67.mp3';var got=_hasAudioFor('و'+STEM);delete YOUTUBE_AUDIO[STEM];return got===true?'ok':'BAD_'+got;}catch(e){return 'THROWS_'+e.message;}})()",
  r67_urlForBareHitsSuffixed: "(function(){try{if(typeof YOUTUBE_AUDIO==='undefined')return 'NO_YT';var STEM='probe67suf';YOUTUBE_AUDIO[STEM]='stub67b.mp3';var url=_audioUrlFor(STEM+'ها');delete YOUTUBE_AUDIO[STEM];return url==='stub67b.mp3'?'ok':'BAD_'+url;}catch(e){return 'THROWS_'+e.message;}})()",
  // Run #68 — BUG FIX: progress tracking doesn't update live. recordActivity now drives updateNavStats (nav-due, nav-total, streak, XP, today-dashboard) and re-renders stats view if active
  r68_recordActivityCallsNavStats: "(function(){try{var src=String(recordActivity);return src.indexOf('updateNavStats')>=0?'ok':'MISSING_CALL';}catch(e){return 'THROWS_'+e.message;}})()",
  r68_recordActivityRerendersStats: "(function(){try{var src=String(recordActivity);return src.indexOf('renderStats')>=0?'ok':'MISSING_RERENDER';}catch(e){return 'THROWS_'+e.message;}})()",
  r68_recordActivityStillWritesActivity: "(function(){try{var src=String(recordActivity);return src.indexOf('la_activity')>=0?'ok':'MISSING_WRITE';}catch(e){return 'THROWS_'+e.message;}})()",
  r68_updateNavStatsStillCallsUpdateStreak: "(function(){try{var src=String(updateNavStats);return src.indexOf('updateStreak')>=0?'ok':'MISSING_STREAK';}catch(e){return 'THROWS_'+e.message;}})()",
  r68_recordActivityIncrementsCount: "(function(){try{var mem={};var orig=localStorage;localStorage={getItem:function(k){return mem[k]||null;},setItem:function(k,v){mem[k]=String(v);},removeItem:function(k){delete mem[k];}};recordActivity();var a1=JSON.parse(mem.la_activity||'{}');var t=todayKey();var c1=a1[t]||0;recordActivity();var a2=JSON.parse(mem.la_activity||'{}');var c2=a2[t]||0;localStorage=orig;return (c1===1&&c2===2)?'ok':'BAD_c1='+c1+'_c2='+c2;}catch(e){return 'THROWS_'+e.message;}})()",
  r68_recordActivityHasFallback: "(function(){try{var src=String(recordActivity);return src.indexOf('updateStreak()')>=0&&src.indexOf('typeof updateNavStats')>=0?'ok':'MISSING_FALLBACK';}catch(e){return 'THROWS_'+e.message;}})()",
  // Run #69 — NEW FEATURE: Dialogue Pragmatics Drill (dpr) — pick real meaning/implication of Lebanese expressions
  fn_openDpr:   "typeof openDpr==='function'",
  fn_closeDpr:  "typeof closeDpr==='function'",
  fn_setDprTab: "typeof setDprTab==='function'",
  fn_renderDpr: "typeof renderDpr==='function'",
  fn_dprAnswer: "typeof dprAnswer==='function'",
  fn_dprNext:   "typeof dprNext==='function'",
  dprItems:     "typeof DPR_ITEMS!=='undefined'?DPR_ITEMS.length:'UNDEF'",
  dprTips:      "typeof DPR_TIPS!=='undefined'?DPR_TIPS.length:'UNDEF'",
  r69_itemsHaveRequiredFields: "(function(){try{for(var i=0;i<DPR_ITEMS.length;i++){var it=DPR_ITEMS[i];if(!it.id||!it.sentence||!it.translit||!it.surface||!it.implications||it.implications.length!==4)return 'BAD_'+i+':'+(it.id||'NO_ID');}return 'ok';}catch(e){return 'THROWS_'+e.message;}})()",
  r69_exactlyOneCorrectPerItem: "(function(){try{for(var i=0;i<DPR_ITEMS.length;i++){var it=DPR_ITEMS[i];var n=0;for(var j=0;j<it.implications.length;j++)if(it.implications[j].correct)n++;if(n!==1)return 'BAD_'+it.id+'_has_'+n+'_correct';}return 'ok';}catch(e){return 'THROWS_'+e.message;}})()",
  r69_implicationsAllHaveText: "(function(){try{for(var i=0;i<DPR_ITEMS.length;i++){var it=DPR_ITEMS[i];for(var j=0;j<it.implications.length;j++)if(!it.implications[j].text)return 'BAD_'+it.id+'['+j+']';}return 'ok';}catch(e){return 'THROWS_'+e.message;}})()",
  r69_implicationsUniqueTextPerItem: "(function(){try{for(var i=0;i<DPR_ITEMS.length;i++){var it=DPR_ITEMS[i];var s={};for(var j=0;j<it.implications.length;j++){if(s[it.implications[j].text])return 'DUPE_'+it.id;s[it.implications[j].text]=true;}}return 'ok';}catch(e){return 'THROWS_'+e.message;}})()",
  r69_dprRegisteredInTopics: "(function(){try{for(var i=0;i<TOPICS_CATEGORIES.length;i++)for(var j=0;j<TOPICS_CATEGORIES[i].items.length;j++)if(TOPICS_CATEGORIES[i].items[j].fn==='openDpr')return 'ok_'+TOPICS_CATEGORIES[i].id;return 'MISSING';}catch(e){return 'THROWS_'+e.message;}})()",
  r69_dprCorrectIncrements: "(function(){try{_dprScore={correct:0,total:0};_dprBuildOrder();var it=_dprCurrentItem();var correctIdx=-1;for(var k=0;k<it.implications.length;k++)if(it.implications[k].correct){correctIdx=k;break;}dprAnswer(correctIdx);return (_dprScore.correct===1&&_dprScore.total===1)?'ok':'BAD_c='+_dprScore.correct+'_t='+_dprScore.total;}catch(e){return 'THROWS_'+e.message;}})()",
  r69_dprWrongDoesNotIncrementCorrect: "(function(){try{_dprScore={correct:0,total:0};_dprBuildOrder();var it=_dprCurrentItem();var wrongIdx=-1;for(var k=0;k<it.implications.length;k++)if(!it.implications[k].correct){wrongIdx=k;break;}dprAnswer(wrongIdx);return (_dprScore.correct===0&&_dprScore.total===1)?'ok':'BAD_c='+_dprScore.correct+'_t='+_dprScore.total;}catch(e){return 'THROWS_'+e.message;}})()",
  r69_dprSecondAnswerLocked: "(function(){try{_dprScore={correct:0,total:0};_dprBuildOrder();var it=_dprCurrentItem();dprAnswer(0);dprAnswer(1);return _dprScore.total===1?'ok':'BAD_double_count_'+_dprScore.total;}catch(e){return 'THROWS_'+e.message;}})()",
  // Run #70 — AUDIO: finer Lebanese-proximity TTS voice priority list + quality bonus
  r70_voicePriorityListSize: "typeof TTS_VOICE_PRIORITY_LB!=='undefined'?TTS_VOICE_PRIORITY_LB.length:'UNDEF'",
  r70_qualityBonusListSize:  "typeof TTS_VOICE_QUALITY_BONUS!=='undefined'?TTS_VOICE_QUALITY_BONUS.length:'UNDEF'",
  r70_lebaneseScoresHighest: "(function(){try{var lb=_scoreVoice({lang:'ar-LB',name:'Lebanese'});var sy=_scoreVoice({lang:'ar-SY',name:'Syrian'});var eg=_scoreVoice({lang:'ar-EG',name:'Egyptian'});var ma=_scoreVoice({lang:'ar-MA',name:'Moroccan'});return (lb>sy&&sy>eg&&eg>ma)?'ok':'BAD_lb='+lb+'_sy='+sy+'_eg='+eg+'_ma='+ma;}catch(e){return 'THROWS_'+e.message;}})()",
  r70_qualityBonusApplied:   "(function(){try{var basic=_scoreVoice({lang:'ar-EG',name:'Egyptian'});var neural=_scoreVoice({lang:'ar-EG',name:'Egyptian Neural'});return (neural===basic+10)?'ok':'BAD_basic='+basic+'_neural='+neural;}catch(e){return 'THROWS_'+e.message;}})()",
