  r95_activityUsesLsSet: "(function(){try{var src=String(__APP_SRC);var hasLsSet=/_lsSet\\s*\\(\\s*['\"]la_activity/.test(src);var bareCount=(src.match(/localStorage\\.setItem\\s*\\(\\s*['\"]la_activity/g)||[]).length;return (hasLsSet&&bareCount===0)?'ok':'BAD_ls='+hasLsSet+'_bare='+bareCount;}catch(e){return 'THROWS_'+e.message;}})()",
