  r95_proverbProgressUsesLsSet: "(function(){try{var src=String(saveProverbProgress);var has=src.indexOf(\"_lsSet('la_proverb_progress'\")>=0;var bare=/localStorage\\.setItem\\s*\\(\\s*['\"]la_proverb_progress/.test(src);return (has&&!bare)?'ok':'BAD_has='+has+'_bare='+bare;}catch(e){return 'THROWS_'+e.message;}})()",
