  r95_activitySurvivesQuotaThrow: "(function(){try{var mem={};var threw=false;var oLS=localStorage;localStorage={getItem:function(k){return mem[k]||null;},setItem:function(k,v){if(!threw&&k==='la_activity'){threw=true;var e=new Error('QuotaExceededError');e.name='QuotaExceededError';throw e;}mem[k]=String(v);},removeItem:function(k){delete mem[k];}};mem[CACHE_KEY]=JSON.stringify({stuff:'x'});recordActivity();localStorage=oLS;return (mem['la_activity']&&mem['la_activity'].length>0&&!(CACHE_KEY in mem))?'ok':'BAD_act='+!!mem['la_activity']+'_cacheGone='+!(CACHE_KEY in mem);}catch(e){return 'THROWS_'+e.message;}})()",

