  r96_idmRegisteredInTopics: "(function(){try{var conv=TOPICS_CATEGORIES.find(function(c){return c.id==='conv';});if(!conv)return 'MISSING_conv';var found=conv.items.find(function(it){return it.fn==='openIdm';});return found?'ok':'MISSING_idm_entry';}catch(e){return 'THROWS_'+e.message;}})()",
