  r98_getNoneStoredReturnsMinusOne: "(function(){try{var oALG=_alSettings;_alSettings=function(){return {};};var got=getPreferredVoiceIdx();_alSettings=oALG;return got===-1?'ok':'BAD_got='+got;}catch(e){return 'THROWS_'+e.message;}})()",
  r98_setClearsIdentityOnInvalidIdx: "(function(){try{var oALS=_alSaveSettings;var oALG=_alSettings;var saved=null;_alSaveSettings=function(s){saved=s;};_alSettings=function(){return {voiceName:'Old',voiceLang:'ar-LB'};};var oAV=_arVoices;_arVoices=[{name:'A',lang:'ar-LB'}];setPreferredVoiceIdx(-1);_alSaveSettings=oALS;_alSettings=oALG;_arVoices=oAV;return (saved&&saved.voiceIdx===-1&&!('voiceName' in saved)&&!('voiceLang' in saved))?'ok':'BAD_'+JSON.stringify(saved);}catch(e){return 'THROWS_'+e.message;}})()",
