  r99_allExchangesFullSchema: "(function(){try{var bad=STC_EXCHANGES.filter(function(x){return !(x.opener&&x.opener.ar&&x.opener.tr&&x.opener.en&&x.reply&&x.reply.ar&&x.reply.tr&&x.reply.en&&x.note&&x.topic);});return bad.length===0?'ok':'BAD_missing='+JSON.stringify(bad.map(function(x){return x.id;}));}catch(e){return 'THROWS_'+e.message;}})()",
  r99_stcRegisteredInTopics: "(function(){try{var conv=TOPICS_CATEGORIES.find(function(c){return c.id==='conv';});if(!conv)return 'MISSING_conv';var found=conv.items.find(function(it){return it.fn==='openStc';});return found?'ok':'MISSING_stc_entry';}catch(e){return 'THROWS_'+e.message;}})()",
  r99_buildOptionsHasOneCorrect: "(function(){try{var ex=STC_EXERCISES[0];var opts=_stcBuildOptions(ex);var correct=opts.filter(function(o){return o&&o.correct===true;});return (opts.length>=2&&opts.length<=4&&correct.length===1&&correct[0].id===ex.exchangeId)?'ok_n='+opts.length:'BAD_opts='+opts.length+'_correct='+correct.length;}catch(e){return 'THROWS_'+e.message;}})()",
  r99_distractorsSameTopic: "(function(){try{var ex=STC_EXERCISES[0];var target=STC_EXCHANGES.find(function(x){return x.id===ex.exchangeId;});var opts=_stcBuildOptions(ex);var allSameTopic=opts.every(function(o){var x=STC_EXCHANGES.find(function(y){return y.id===o.id;});return x&&x.topic===target.topic;});return allSameTopic?'ok':'BAD_cross_topic';}catch(e){return 'THROWS_'+e.message;}})()",
  r99_correctIncrements: "(function(){try{_stcScore={correct:0,wrong:0,answered:new Set()};_stcLocked=false;_stcIdx=0;_stcOrder=[STC_EXERCISES[0].id];_stcOptions=_stcBuildOptions(STC_EXERCISES[0]);var idx=_stcOptions.findIndex(function(o){return o.correct;});stcAnswer(idx);return (_stcScore.correct===1&&_stcScore.wrong===0&&_stcLocked===true)?'ok':'BAD_c='+_stcScore.correct+'_w='+_stcScore.wrong+'_lock='+_stcLocked;}catch(e){return 'THROWS_'+e.message;}})()",
  r99_wrongIncrements: "(function(){try{_stcScore={correct:0,wrong:0,answered:new Set()};_stcLocked=false;_stcIdx=0;_stcOrder=[STC_EXERCISES[0].id];_stcOptions=_stcBuildOptions(STC_EXERCISES[0]);var idx=_stcOptions.findIndex(function(o){return !o.correct;});stcAnswer(idx);return (_stcScore.correct===0&&_stcScore.wrong===1)?'ok':'BAD_c='+_stcScore.correct+'_w='+_stcScore.wrong;}catch(e){return 'THROWS_'+e.message;}})()",
