  r99_filterNarrowsByTopic: "(function(){try{_stcFilter='closing';_stcOrder=_stcFilteredExercises().map(function(e){return e.id;});var allClosing=_stcOrder.every(function(id){var e=STC_EXERCISES.find(function(y){return y.id===id;});var x=STC_EXCHANGES.find(function(z){return z.id===e.exchangeId;});return x&&x.topic==='closing';});var n=_stcOrder.length;_stcFilter='all';_stcOrder=_stcFilteredExercises().map(function(e){return e.id;});return (allClosing&&n>=2)?'ok_n='+n:'BAD_allClosing='+allClosing+'_n='+n;}catch(e){return 'THROWS_'+e.message;}})()",

  // Run #100 — AUDIO (milestone): Audio Metrics Dashboard. Session counters
