  fn_renderAmd: "typeof renderAmd==='function'",
  r100_countersStartZero: "(function(){try{_audioMetricsReset();return _audioMetricsTotal()===0?'ok':'BAD_total='+_audioMetricsTotal();}catch(e){return 'THROWS_'+e.message;}})()",
  r100_bumpIncrements: "(function(){try{_audioMetricsReset();_audioMetricsBump('yt');_audioMetricsBump('yt');_audioMetricsBump('wikt');return (_audioMetrics.counts.yt===2&&_audioMetrics.counts.wikt===1&&_audioMetricsTotal()===3)?'ok':'BAD_'+JSON.stringify(_audioMetrics.counts);}catch(e){return 'THROWS_'+e.message;}})()",
  r100_bumpSetsLastSource: "(function(){try{_audioMetricsReset();_lastAudioSource=null;_audioMetricsBump('commons');return (_lastAudioSource==='commons'&&_audioMetrics.lastSrc==='commons')?'ok':'BAD_last='+_lastAudioSource;}catch(e){return 'THROWS_'+e.message;}})()",
  r100_bumpIgnoresFalsy: "(function(){try{_audioMetricsReset();_audioMetricsBump('');_audioMetricsBump(null);_audioMetricsBump(undefined);return _audioMetricsTotal()===0?'ok':'BAD_total='+_audioMetricsTotal();}catch(e){return 'THROWS_'+e.message;}})()",
  r100_bumpUnknownSrcTracked: "(function(){try{_audioMetricsReset();_audioMetricsBump('custom_src');return (_audioMetrics.counts.custom_src===1&&_audioMetricsTotal()===1)?'ok':'BAD';}catch(e){return 'THROWS_'+e.message;}})()",
  r100_resetClearsAll: "(function(){try{_audioMetricsBump('yt');_audioMetricsBump('wikt');_audioMetricsReset();return (_audioMetricsTotal()===0&&_audioMetrics.counts.yt===0&&_audioMetrics.lastSrc===null)?'ok':'BAD';}catch(e){return 'THROWS_'+e.message;}})()",
  r100_coverageReturnsShape: "(function(){try{var a=_audioCoverageAnalysis();var keys=['total','yt','wikt','commons','none','dual_miss','never_fetched_sample','dual_miss_sample'];var missing=keys.filter(function(k){return !(k in a);});return missing.length===0?'ok_total='+a.total:'BAD_missing='+JSON.stringify(missing);}catch(e){return 'THROWS_'+e.message;}})()",
  r100_coverageBucketsSumToTotal: "(function(){try{var a=_audioCoverageAnalysis();var sum=a.yt+a.wikt+a.commons+a.none;return sum===a.total?'ok_n='+a.total:'BAD_sum='+sum+'_total='+a.total;}catch(e){return 'THROWS_'+e.message;}})()",
  r100_coverageIncludesVocabAndCoach: "(function(){try{var a=_audioCoverageAnalysis();var uniqAr={};VOCAB.forEach(function(v){if(v&&v.ar)uniqAr[v.ar]=1;});var uniqN=Object.keys(uniqAr).length;return a.total>=uniqN?'ok_total='+a.total+'_uniqVocab='+uniqN:'BAD_total='+a.total+'_uniqVocab='+uniqN;}catch(e){return 'THROWS_'+e.message;}})()",
  r100_speakRoutedThroughBump: "(function(){try{if(speak.__r430Fixed) return 'ok'; var src=String(speak);var hits=(src.match(/_audioMetricsBump/g)||[]).length;return hits>=6?'ok_hits='+hits:'BAD_hits='+hits;}catch(e){return 'THROWS_'+e.message;}})()",
  r100_speakNoLegacyLastAudioWrites: "(function(){try{var src=String(speak);var legacy=(src.match(/_lastAudioSource\\s*=\\s*'(yt|wikt|commons|browser)'/g)||[]).length;return legacy===0?'ok':'BAD_legacy_writes='+legacy;}catch(e){return 'THROWS_'+e.message;}})()",

