  // ===== run #119 BUG FIX =====
  // segmentSentence was tagging cached chunks as source:'local' because
  // _audioUrlFor returns a URL for both YT and cache hits — the
  // `url ? 'local' : 'cache'` ternary was dead-coded. That caused
  // sentencePlaybackPlan (Run #118) to mislabel Wiktionary/Commons
  // recordings as "🎬 local YouTube recording". Fix: probe YT map
  // directly in segmentSentence to distinguish origin.
  r119_segmentSentenceProbesYtMap: "(function(){try{return String(segmentSentence).indexOf('_ytMap119')>=0?'ok':'BAD';}catch(e){return 'THROWS_'+e.message;}})()",
  r119_ytChunkTaggedLocal: "(function(){try{if(typeof YOUTUBE_AUDIO==='undefined')return 'skip_no_yt';var keys=Object.keys(YOUTUBE_AUDIO);if(!keys.length)return 'skip_empty';var c=segmentSentence(keys[0]);if(!c.length||!c[0].hasAudio)return 'skip_no_chunk';return c[0].source==='local'?'ok':'BAD_got='+c[0].source;}catch(e){return 'THROWS_'+e.message;}})()",
  r119_cacheOnlyChunkTaggedCache: "(function(){try{var fakeKey='zzzr119cacheonlykey';if(typeof YOUTUBE_AUDIO!=='undefined' && YOUTUBE_AUDIO[fakeKey])return 'skip_yt_collision';var origHas=_hasAudioFor;var origUrl=_audioUrlFor;_hasAudioFor=function(t){return t===fakeKey;};_audioUrlFor=function(t){return t===fakeKey?'https://example.com/fake.mp3':null;};var c=segmentSentence(fakeKey);_hasAudioFor=origHas;_audioUrlFor=origUrl;if(!c.length||!c[0].hasAudio)return 'skip_no_chunk';return c[0].source==='cache'?'ok':'BAD_got='+c[0].source;}catch(e){return 'THROWS_'+e.message;}})()",
  r119_planLabelMatchesOrigin: "(function(){try{if(typeof YOUTUBE_AUDIO==='undefined')return 'skip';var keys=Object.keys(YOUTUBE_AUDIO);if(!keys.length)return 'skip';var plan=sentencePlaybackPlan(keys[0]);if(!plan.length)return 'skip';var first=plan[0];if(!first.hasAudio)return 'skip';return (first.source==='local' && first.reason.indexOf('YouTube')>=0)?'ok':'BAD_source='+first.source+'_reason='+first.reason.slice(0,40);}catch(e){return 'THROWS_'+e.message;}})()",
