  r126_cvgItemsHaveShape: "(function(){try{var req=['id','cat','context','gap','distractors','note'];for(var i=0;i<CVG_ITEMS.length;i++){for(var j=0;j<req.length;j++){if(!(req[j] in CVG_ITEMS[i]))return 'BAD_missing='+req[j]+'_at='+i;}}return 'ok';}catch(e){return 'THROWS_'+e.message;}})()",
  r126_cvgGapShape: "(function(){try{var req=['s','ar','tr','en'];for(var i=0;i<CVG_ITEMS.length;i++){var g=CVG_ITEMS[i].gap;for(var j=0;j<req.length;j++){if(!(req[j] in g))return 'BAD_missing='+req[j]+'_at='+i;}}return 'ok';}catch(e){return 'THROWS_'+e.message;}})()",
