  r126_cvgTwoDistractors: "(function(){try{for(var i=0;i<CVG_ITEMS.length;i++){if(!Array.isArray(CVG_ITEMS[i].distractors) || CVG_ITEMS[i].distractors.length!==2)return 'BAD_at='+i+'_n='+(CVG_ITEMS[i].distractors||[]).length;}return 'ok';}catch(e){return 'THROWS_'+e.message;}})()",
  r126_cvgCatsValid: "(function(){try{var valid={greet:1,shop:1,food:1,travel:1,life:1};for(var i=0;i<CVG_ITEMS.length;i++){if(!valid[CVG_ITEMS[i].cat])return 'BAD_cat='+CVG_ITEMS[i].cat;}return 'ok';}catch(e){return 'THROWS_'+e.message;}})()",
  r126_cvgAllCatsCovered: "(function(){try{var seen={};CVG_ITEMS.forEach(function(it){seen[it.cat]=1;});var need=['greet','shop','food','travel','life'];for(var i=0;i<need.length;i++){if(!seen[need[i]])return 'BAD_missing='+need[i];}return 'ok';}catch(e){return 'THROWS_'+e.message;}})()",
  r126_cvgIdsUnique: "(function(){try{var seen={};for(var i=0;i<CVG_ITEMS.length;i++){var id=CVG_ITEMS[i].id;if(seen[id])return 'BAD_dup='+id;seen[id]=1;}return 'ok';}catch(e){return 'THROWS_'+e.message;}})()",
