  r126_cvgAnswerCorrectBumpsScore: "(function(){try{openCvg();var item=_cvgCurrentItem();if(!item)return 'BAD_no_item';var correctIdx=_cvgOptions.findIndex(function(o){return o.correct;});if(correctIdx<0)return 'BAD_no_correct';var before=_cvgScore.correct;cvgAnswer(correctIdx);return _cvgScore.correct===before+1?'ok':'BAD_delta='+(_cvgScore.correct-before);}catch(e){return 'THROWS_'+e.message;}})()",
