  r126_cvgFilterWorks: "(function(){try{openCvg();cvgSetFilter('food');var items=_cvgFilteredItems();if(!items.length)return 'BAD_empty';for(var i=0;i<items.length;i++){if(items[i].cat!=='food')return 'BAD_cat='+items[i].cat;}return 'ok_n='+items.length;}catch(e){return 'THROWS_'+e.message;}})()",
