  r127_drillRenderIncludesPlayAll: "(function(){try{openCvg();var called=false;var sharedEl={innerHTML:'',style:{},textContent:''};var origGet=document.getElementById;document.getElementById=function(id){if(id==='cvg-content'||id==='cvg-stats')return sharedEl;return origGet(id);};_cvgRenderDrill();document.getElementById=origGet;return sharedEl.innerHTML.indexOf('cvgPlayDialog')>=0 && sharedEl.innerHTML.indexOf('Play whole dialog')>=0?'ok':'BAD';}catch(e){return 'THROWS_'+e.message;}})()",
