  // ─── Run #131 BUG FIX: lat input escape + normalize over-collapse ──────
  // (a) _latRenderDrill rendered input value using a raw .replace(/"/,'&quot;')
  //     which missed <, >, &, ' — a user typing an attribute-breaking payload
  //     could escape the quoted attr and inject events. Now uses escapeHtml
  //     (existing full-escape helper from R29-era welcome flow).
  // (b) _latNormalize had over-aggressive digraph collapse (sh→s/kh→k/gh→g/
  //     dh→d) meant to ease emphatic forgiveness. Side effect: merged
  //     distinct letters (ش ≠ س, خ ≠ ك, غ ≠ غ, ذ ≠ د). Example: target
  //     'shams' (sun) vs typo 'sams' both collapsed to 'sams' — false
  //     perfect. Emphatic forgiveness already handled by toLowerCase (uppercase
  //     emphatic markers S/T/D/DH lowercase cleanly). Collapse removed.
  r131_latInputUsesEscapeHtml: "(function(){try{return String(_latRenderDrill).indexOf('escapeHtml(_latInput)')>=0?'ok':'BAD';}catch(e){return 'THROWS_'+e.message;}})()",
  r131_latInputNoRawReplaceQuote: "(function(){try{var src=String(_latRenderDrill);return src.indexOf(\"_latInput).replace(/\")<0?'ok':'BAD_still_has_raw';}catch(e){return 'THROWS_'+e.message;}})()",
  r131_escapeHtmlHandlesLtGt: "(function(){try{var s=escapeHtml('<script>');return s==='&lt;script&gt;'?'ok':'BAD_s='+s;}catch(e){return 'THROWS_'+e.message;}})()",
  r131_escapeHtmlHandlesAmp: "(function(){try{var s=escapeHtml('a & b');return s==='a &amp; b'?'ok':'BAD_s='+s;}catch(e){return 'THROWS_'+e.message;}})()",
  r131_escapeHtmlHandlesQuote: "(function(){try{var s=escapeHtml('a\"b');return s==='a&quot;b'?'ok':'BAD_s='+s;}catch(e){return 'THROWS_'+e.message;}})()",
  r131_latRenderEscapesMaliciousInput: "(function(){try{openLat();_latInput='\"onerror=alert(1) x=\"';var sharedEl={innerHTML:'',style:{},textContent:''};var origGet=document.getElementById;document.getElementById=function(id){if(id==='lat-content'||id==='lat-stats')return sharedEl;return origGet(id);};_latRenderDrill();document.getElementById=origGet;var html=sharedEl.innerHTML;var hasRaw=html.indexOf('\"onerror=alert')>=0;var hasEsc=html.indexOf('&quot;onerror=alert')>=0;return (!hasRaw && hasEsc)?'ok':'BAD_raw='+hasRaw+'_esc='+hasEsc;}catch(e){return 'THROWS_'+e.message;}})()",
  r131_normalizeKeepsShDistinct: "(function(){try{var a=_latNormalize('shams');var b=_latNormalize('sams');return a!==b?'ok':'BAD_merged='+a;}catch(e){return 'THROWS_'+e.message;}})()",
  r131_normalizeKeepsKhDistinct: "(function(){try{var a=_latNormalize('khobz');var b=_latNormalize('kobz');return a!==b?'ok':'BAD_merged='+a;}catch(e){return 'THROWS_'+e.message;}})()",
  r131_normalizeKeepsGhDistinct: "(function(){try{var a=_latNormalize('ghali');var b=_latNormalize('gali');return a!==b?'ok':'BAD_merged='+a;}catch(e){return 'THROWS_'+e.message;}})()",
  r131_normalizeKeepsDhDistinct: "(function(){try{var a=_latNormalize('dhib');var b=_latNormalize('dib');return a!==b?'ok':'BAD_merged='+a;}catch(e){return 'THROWS_'+e.message;}})()",
  r131_normalizeEmphaticStillCaseInsensitive: "(function(){try{var a=_latNormalize('Sabr');var b=_latNormalize('sabr');return a===b?'ok':'BAD a='+a+' b='+b;}catch(e){return 'THROWS_'+e.message;}})()",
