  r134_addXpAccumulatesXpToday: "(function(){try{var mem={};var orig=localStorage;localStorage={getItem:function(k){return k in mem?mem[k]:null;},setItem:function(k,v){mem[k]=String(v);},removeItem:function(k){delete mem[k];}};addXp(10);addXp(15);localStorage=orig;var raw=JSON.parse(mem.la_xp_today||'{}');var k=todayKey();return raw[k]===25?'ok':'BAD_val='+raw[k];}catch(e){return 'THROWS_'+e.message;}})()",
  r134_addXpZeroDoesNotTouch: "(function(){try{var mem={};var orig=localStorage;localStorage={getItem:function(k){return k in mem?mem[k]:null;},setItem:function(k,v){mem[k]=String(v);},removeItem:function(k){delete mem[k];}};addXp(0);localStorage=orig;return !('la_xp_today' in mem)?'ok_untouched':'BAD_wrote='+mem.la_xp_today;}catch(e){return 'THROWS_'+e.message;}})()",
