  r134_addXpHistoryCap: "(function(){try{var huge={};for(var i=0;i<200;i++){huge['2024-01-'+String(i).padStart(2,'0')]=5;}var mem={la_xp_today:JSON.stringify(huge)};var orig=localStorage;localStorage={getItem:function(k){return k in mem?mem[k]:null;},setItem:function(k,v){mem[k]=String(v);},removeItem:function(k){delete mem[k];}};addXp(10);localStorage=orig;var raw=JSON.parse(mem.la_xp_today||'{}');var n=Object.keys(raw).length;return n<=181?'ok_n='+n:'BAD_n='+n;}catch(e){return 'THROWS_'+e.message;}})()",
