  r136_coverageForTextsMissingSampleCap: "(function(){try{var manyMissing=[];for(var i=0;i<20;i++)manyMissing.push('zz_miss_'+i);var r=_prgAudioCoverageForTexts(manyMissing);return r.missingSamples.length<=6?'ok_n='+r.missingSamples.length:'BAD_n='+r.missingSamples.length;}catch(e){return 'THROWS_'+e.message;}})()",
  r136_coverageFullHasPdxAndLat: "(function(){try{var c=_prgAudioCoverage();var ids=c.map(function(x){return x.id;});return (ids.indexOf('pdx')>=0 && ids.indexOf('lat')>=0 && ids.indexOf('vocab100')>=0)?'ok':'BAD_ids='+ids.join(',');}catch(e){return 'THROWS_'+e.message;}})()",
