  r136_audioBarProducesSvgFreeHtml: "(function(){try{var h=_prgAudioBar({total:10,lebanese:5,fallback:3,none:2});return (h.indexOf('width:50%')>=0 && h.indexOf('width:30%')>=0 && h.indexOf('width:20%')>=0)?'ok':'BAD_'+h.slice(0,80);}catch(e){return 'THROWS_'+e.message;}})()",
