  r136_renderAudioProducesHtml: "(function(){try{var el={innerHTML:''};var origGet=document.getElementById;document.getElementById=function(id){if(id==='prg-content')return el;return origGet(id);};_prgTab='audio';renderPrg();document.getElementById=origGet;return (el.innerHTML.indexOf('Overall Lebanese audio coverage')>=0 && el.innerHTML.indexOf('Pair Discrimination')>=0)?'ok':'BAD_'+el.innerHTML.slice(0,100);}catch(e){return 'THROWS_'+e.message;}})()",
