  // === R137 BUG FIX ===
  // pdx drill was playing nonsense distractor strings 50% of rounds
  // (pdx06/11/12/13 b-sides marked "(nonsense, drill)"). When TTS fell
  // through to MSA synth for those, users heard wrong-dialect audio for
  // words that don't exist. pdx15 was unsolvable (both translits "hada").
  // Fix: isDrill flag forces _pdxAsideKey to real side; skipDrill filters
  // pdx15 out of the drill pool. _prgAudioCoverage + _pdxAudioTargets now
  // also respect these flags, un-inflating the "no audio" denominator.
  r137_dataIsDrillFlaggedCount: "(function(){try{var n=PDX_PAIRS.filter(function(p){return p.b && p.b.isDrill;}).length;return n===4?'ok':'BAD_n='+n;}catch(e){return 'THROWS_'+e.message;}})()",
  r137_dataSkipDrillFlaggedCount: "(function(){try{var n=PDX_PAIRS.filter(function(p){return p.skipDrill;}).length;return n===1?'ok':'BAD_n='+n;}catch(e){return 'THROWS_'+e.message;}})()",
  r137_dataPdx15SkipDrill: "(function(){try{var p=PDX_PAIRS.find(function(x){return x.id==='pdx15';});return (p && p.skipDrill===true)?'ok':'BAD';}catch(e){return 'THROWS_'+e.message;}})()",
  r137_dataPdx06bIsDrill: "(function(){try{var p=PDX_PAIRS.find(function(x){return x.id==='pdx06';});return (p && p.b.isDrill===true)?'ok':'BAD';}catch(e){return 'THROWS_'+e.message;}})()",
  r137_dataPdx11bIsDrill: "(function(){try{var p=PDX_PAIRS.find(function(x){return x.id==='pdx11';});return (p && p.b.isDrill===true)?'ok':'BAD';}catch(e){return 'THROWS_'+e.message;}})()",
  r137_dataPdx12bIsDrill: "(function(){try{var p=PDX_PAIRS.find(function(x){return x.id==='pdx12';});return (p && p.b.isDrill===true)?'ok':'BAD';}catch(e){return 'THROWS_'+e.message;}})()",
  r137_dataPdx13bIsDrill: "(function(){try{var p=PDX_PAIRS.find(function(x){return x.id==='pdx13';});return (p && p.b.isDrill===true)?'ok':'BAD';}catch(e){return 'THROWS_'+e.message;}})()",
  r137_dataRealSidesHaveNoDrillFlag: "(function(){try{var n=PDX_PAIRS.filter(function(p){return p.a && p.a.isDrill;}).length;return n===0?'ok':'BAD_a_sides_flagged='+n;}catch(e){return 'THROWS_'+e.message;}})()",
  r137_filteredPairsExcludesSkipDrill: "(function(){try{openPdx();pdxSetFilter('all');var ids=_pdxItems.map(function(p){return p.id;});return ids.indexOf('pdx15')<0?'ok':'BAD_still_present';}catch(e){return 'THROWS_'+e.message;}})()",
  r137_filteredPairsCountIs19: "(function(){try{openPdx();pdxSetFilter('all');return _pdxItems.length===19?'ok':'BAD_n='+_pdxItems.length;}catch(e){return 'THROWS_'+e.message;}})()",
  r137_filteredPairsDhFilterExcludesPdx15: "(function(){try{openPdx();pdxSetFilter('dh');var n=_pdxItems.length;var hasPdx15=_pdxItems.some(function(p){return p.id==='pdx15';});return (n===4 && !hasPdx15)?'ok':'BAD_n='+n+'_hasPdx15='+hasPdx15;}catch(e){return 'THROWS_'+e.message;}})()",
  r137_loadCurrentNeverLandsOnDrillSide: "(function(){try{openPdx();pdxSetFilter('kh');for(var i=0;i<20;i++){_pdxIdx=_pdxItems.findIndex(function(p){return p.id==='pdx06';});_pdxLoadCurrent();var cur=_pdxItems[_pdxIdx];if(cur[_pdxAsideKey].isDrill)return 'BAD_landed_on_drill_iter='+i;}return 'ok';}catch(e){return 'THROWS_'+e.message;}})()",
  r137_loadCurrentPicksAOnPdx06: "(function(){try{openPdx();pdxSetFilter('kh');_pdxIdx=_pdxItems.findIndex(function(p){return p.id==='pdx06';});_pdxLoadCurrent();return _pdxAsideKey==='a'?'ok':'BAD_key='+_pdxAsideKey;}catch(e){return 'THROWS_'+e.message;}})()",
  r137_audioCoverageExcludesDrill: "(function(){try{var c=_prgAudioCoverage();var pdx=c.find(function(x){return x.id==='pdx';});return pdx.stats.total===34?'ok':'BAD_n='+pdx.stats.total;}catch(e){return 'THROWS_'+e.message;}})()",
  r137_audioCoverageExcludesPdx15Sides: "(function(){try{var c=_prgAudioCoverage();var pdx=c.find(function(x){return x.id==='pdx';});return (pdx.stats.total===34)?'ok_34=20x2-4drill-2skip':'BAD_n='+pdx.stats.total;}catch(e){return 'THROWS_'+e.message;}})()",
  r137_pdxAudioTargetsExcludesDrill: "(function(){try{var t=_pdxAudioTargets();var hasDrill=t.some(function(s){return s==='كبز'||s==='دهب'||s==='ديب'||s==='دكي';});return !hasDrill?'ok':'BAD_contains_drill';}catch(e){return 'THROWS_'+e.message;}})()",
  r137_pdxAudioTargetsExcludesPdx15: "(function(){try{var t=_pdxAudioTargets();var hasPdx15=t.some(function(s){return s==='هذا'||s==='هدا';});return !hasPdx15?'ok':'BAD_contains_pdx15';}catch(e){return 'THROWS_'+e.message;}})()",
  r137_pickStillWorksOnPdx06: "(function(){try{openPdx();pdxSetFilter('kh');_pdxIdx=_pdxItems.findIndex(function(p){return p.id==='pdx06';});_pdxLoadCurrent();var before=_pdxStats.attempts;pdxPick('a');return (_pdxStats.attempts===before+1 && _pdxLocked===true)?'ok':'BAD_attempts='+_pdxStats.attempts;}catch(e){return 'THROWS_'+e.message;}})()",
  r137_pickCorrectOnPdx06GivesCorrect: "(function(){try{openPdx();pdxSetFilter('kh');_pdxIdx=_pdxItems.findIndex(function(p){return p.id==='pdx06';});_pdxLoadCurrent();var before=_pdxStats.correct;pdxPick(_pdxAsideKey);return (_pdxStats.correct===before+1)?'ok':'BAD';}catch(e){return 'THROWS_'+e.message;}})()",
  r137_replayNeverSpeaksNonsense: "(function(){try{openPdx();pdxSetFilter('kh');_pdxIdx=_pdxItems.findIndex(function(p){return p.id==='pdx06';});_pdxLoadCurrent();var item=_pdxItems[_pdxIdx];var toPlay=item[_pdxAsideKey];return (toPlay.ar==='خبز' && !toPlay.isDrill)?'ok':'BAD_ar='+toPlay.ar+'_drill='+toPlay.isDrill;}catch(e){return 'THROWS_'+e.message;}})()",
  r137_browseStillShowsAllPairs: "(function(){try{var src=String(_pdxRenderBrowse);return src.indexOf('PDX_PAIRS.forEach')>=0?'ok':'BAD';}catch(e){return 'THROWS_'+e.message;}})()",
  r137_priorR136CoverageFnIntact: "(function(){try{return typeof _prgAudioCoverage==='function'?'ok':'BAD';}catch(e){return 'THROWS_'+e.message;}})()",
  r137_priorR135PrgIntact: "(function(){try{return typeof openPrg==='function'?'ok':'BAD';}catch(e){return 'THROWS_'+e.message;}})()",
  r137_priorR134XpTodayIntact: "(function(){try{return String(addXp).indexOf('la_xp_today')>=0?'ok':'BAD';}catch(e){return 'THROWS_'+e.message;}})()",
  r137_priorR133PrecacheIntact: "(function(){try{return typeof _audioBulkPrecache==='function'?'ok':'BAD';}catch(e){return 'THROWS_'+e.message;}})()",
