  r138_closeRtbCallsStopAudio: "(function(){try{return String(closeRtb).indexOf('stopAllAudio')>=0?'ok':'BAD';}catch(e){return 'THROWS_'+e.message;}})()",
  r138_allWordsAggregates: "(function(){try{var a=_rtbAllWords();return (a.length>=80 && a[0].word && typeof a[0].rootIdx==='number')?'ok_n='+a.length:'BAD';}catch(e){return 'THROWS_'+e.message;}})()",
  r138_drillQueueShuffles: "(function(){try{var q=_rtbBuildDrillQueue();return (Array.isArray(q) && q.length===_rtbAllWords().length)?'ok':'BAD';}catch(e){return 'THROWS_'+e.message;}})()",
  r138_loadDrillProduces4Choices: "(function(){try{openRtb();_rtbLoadDrillItem();return _rtbDrillChoices.length===4?'ok':'BAD_n='+_rtbDrillChoices.length;}catch(e){return 'THROWS_'+e.message;}})()",
  r138_drillChoicesIncludeCorrect: "(function(){try{openRtb();_rtbLoadDrillItem();return _rtbDrillChoices.indexOf(_rtbDrillCorrect)>=0?'ok':'BAD';}catch(e){return 'THROWS_'+e.message;}})()",
  r138_drillChoicesAllUnique: "(function(){try{openRtb();_rtbLoadDrillItem();var seen={};var dup=false;_rtbDrillChoices.forEach(function(x){if(seen[x])dup=true;seen[x]=1;});return !dup?'ok':'BAD_dup';}catch(e){return 'THROWS_'+e.message;}})()",
  r138_pickCorrectBumpsStats: "(function(){try{openRtb();_rtbLoadDrillItem();var b=_rtbStats.correct;var ba=_rtbStats.attempts;rtbPick(_rtbDrillCorrect);return (_rtbStats.correct===b+1 && _rtbStats.attempts===ba+1)?'ok':'BAD';}catch(e){return 'THROWS_'+e.message;}})()",
